export const icon = name => `<svg viewBox="0 0 24 24" aria-hidden="true" class="${name==='arrow'?'arrow':''}">${icons[name]||icons.layers}</svg>`;
export function hydrateIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
let pref='ar';try{pref=localStorage.getItem('autoclip-language')||'ar';}catch{}
const state={lang:languages.includes(pref)?pref:'ar',file:null,url:null,duration:0,start:0,end:0,ratio:'original',clips:[],editingId:null,thumbnail:'',engine:'',token:'',connected:false,projectId:null,previewEnd:null,exporting:false,cancelExport:null,pendingProject:null,analysisAbort:null};
export const t = key => translate(key,state.lang);
export const appState = state;
const video=$('#video');let toastTimer, pendingAction;
export function toast(text,error=false){const el=$('#toast');el.textContent=text;el.classList.toggle('error',error);el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),6000);}
function fail(error){const key=error?.message;toast(t(key)!==key?t(key):t('actionFailed'),true);}
export function setLanguage(lang){if(!languages.includes(lang))return;state.lang=lang;document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';try{localStorage.setItem('autoclip-language',lang);}catch{};document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));document.querySelectorAll('[data-placeholder]').forEach(el=>el.placeholder=t(el.dataset.placeholder));document.querySelectorAll('[data-label]').forEach(el=>{el.setAttribute('aria-label',t(el.dataset.label));el.title=t(el.dataset.label);});document.querySelectorAll('[data-lang]').forEach(el=>{el.classList.toggle('selected',el.dataset.lang===lang);el.setAttribute('aria-pressed',String(el.dataset.lang===lang));});document.title=`AutoClip Studio — ${t('title')}`;updateConnectionLabel();updateRange();renderClips();document.dispatchEvent(new CustomEvent('studio-language',{detail:lang}));}
export function openDialog(id){const el=$('#'+id);if(el&&!el.open)el.showModal();}
export function downloadBlob(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
const safeName = s => String(s).replace(/[<>:"/\\|?*\u0000-\u001f]/g,'').slice(0,90)||'autoclip';
function updateConnectionLabel(){$('#connection-text').textContent=t(state.connected?'engineReady':'localMode');}
function requestReplacement(action){if(state.exporting)return;if(state.clips.length){pendingAction=action;openDialog('confirm-dialog');}else action();}
async function waitMedia(el,event,timeout=20000){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>end(new Error('cannotPlay')),timeout);const done=()=>end(),err=()=>end(new Error('cannotPlay'));function end(error){clearTimeout(timer);el.removeEventListener(event,done);el.removeEventListener('error',err);error?reject(error):resolve();}el.addEventListener(event,done,{once:true});el.addEventListener('error',err,{once:true});});}
function inputFile(){ $('#file-input').value='';$('#file-input').click(); }
async function loadVideo(file){
  if(!file)return;if(!/\.(mp4|mov|webm|m4v)$/i.test(file.name)||file.size===0)throw new Error('invalidVideo');if(file.size>1024**3)throw new Error('largeVideo');
  if(state.pendingProject&&(file.name!==state.pendingProject.source.name||file.size!==state.pendingProject.source.size))throw new Error('wrongOriginal');
  const url=URL.createObjectURL(file),probe=document.createElement('video');probe.preload='metadata';probe.src=url;
  try{const ready=waitMedia(probe,'loadedmetadata');probe.load();await ready;if(!Number.isFinite(probe.duration)||probe.duration<=0)throw new Error('cannotPlay');
    if(state.pendingProject&&Math.abs(probe.duration-state.pendingProject.source.duration)>.2)throw new Error('wrongOriginal');
    video.pause();if(state.url)URL.revokeObjectURL(state.url);state.file=file;state.url=url;state.duration=probe.duration;state.start=0;state.end=Math.min(30,state.duration);state.ratio='original';state.clips=[];state.editingId=null;state.projectId=null;state.thumbnail='';state.previewEnd=null;
    video.src=url;video.load();$('#import-area').hidden=true;$('#player-area').hidden=false;$('#source-badge').textContent=t('videoReady');$('#filename').textContent=file.name;$('#fileinfo').textContent=`${(file.size/1024**2).toFixed(1)} MB · ${formatTime(state.duration)}`;$('#resolution').textContent=`${probe.videoWidth} × ${probe.videoHeight}`;
    for(const id of ['start-time','end-time','start-range','end-range','add-cut','preview-cut'])$('#'+id).disabled=false;
    $('#duration-label').textContent=formatTime(state.duration);$('#start-range').max=state.duration;$('#end-range').max=state.duration;updateRange();renderClips();
    video.addEventListener('loadeddata',()=>{try{const c=document.createElement('canvas');c.width=320;c.height=Math.max(1,Math.round(320*video.videoHeight/video.videoWidth));c.getContext('2d').drawImage(video,0,0,c.width,c.height);state.thumbnail=c.toDataURL('image/jpeg',.72);renderClips();}catch{}},{once:true});
    if(state.pendingProject){const p=state.pendingProject;state.pendingProject=null;restoreClips(p);toast(t('projectRestored'));}else toast(t('fileLoaded'));
    document.dispatchEvent(new CustomEvent('studio-video'));return {name:file.name,duration:state.duration};
  }catch(e){URL.revokeObjectURL(url);throw e;}finally{probe.removeAttribute('src');probe.load();}
}
export function updateRange(){
  $('#start-time').value=formatTime(state.start,true);$('#end-time').value=formatTime(state.end,true);$('#start-range').value=state.start;$('#end-range').value=state.end;$('#cut-duration').textContent=formatTime(state.end-state.start,true);
  $('#range-visual').style.left=`${state.duration?state.start/state.duration*100:0}%`;$('#range-visual').style.width=`${state.duration?(state.end-state.start)/state.duration*100:100}%`;
  $('#aspect-hint').textContent=t(state.ratio==='original'?'originalHint':'cropHint');document.querySelectorAll('[data-ratio]').forEach(b=>{b.classList.toggle('selected',b.dataset.ratio===state.ratio);b.setAttribute('aria-pressed',String(b.dataset.ratio===state.ratio));});
  $('#add-cut [data-i18n]').textContent=t(state.editingId?'saveCut':'addCut');if(state.file)$('#source-badge').textContent=t('videoReady');
}
function readRange(){const start=parseTime($('#start-time').value),end=parseTime($('#end-time').value);if(!validRange(start,end,state.duration))throw new Error('badTime');state.start=start;state.end=end;updateRange();}
export function setSelection(start,end,ratio=state.ratio){if(!state.file)throw new Error('needVideo');if(!validRange(start,end,state.duration)||!['original','9:16','16:9'].includes(ratio))throw new Error('badTime');Object.assign(state,{start,end,ratio});updateRange();return {start,end,ratio};}
export function addClip(title){if(!state.file)throw new Error('needVideo');readRange();if(state.clips.length>=100&&!state.editingId)throw new Error('maxClips');const editing=state.clips.find(c=>c.id===state.editingId);const clip={id:editing?.id||newId(),title:(title||$('#clip-title').value||`${t('untitled')} ${String(state.clips.length+1).padStart(2,'0')}`).slice(0,100),start:state.start,end:state.end,ratio:state.ratio};if(editing)Object.assign(editing,clip);else state.clips.push(clip);state.editingId=null;$('#clip-title').value='';updateRange();renderClips();toast(t(editing?'clipSaved':'clipAdded'));document.dispatchEvent(new CustomEvent('studio-clips'));return clip;}
async function previewClip(clip){if(clip.remote){await previewRemote(clip);return;}if(!state.file)throw new Error('needVideo');video.pause();state.previewEnd=clip.end;video.currentTime=clip.start;await video.play();$('#player-area').scrollIntoView({behavior:'smooth',block:'center'});}
export function renderClips(){const list=$('#clip-list');list.replaceChildren();$('#clip-count').textContent=state.clips.length;$('#nav-count').textContent=state.clips.length;$('#save-project').disabled=!state.clips.length||!state.file;
  if(!state.clips.length){list.innerHTML=`<div class="empty-clips"><span>${icon('layers')}</span><div><h3>${t('emptyTitle')}</h3><p>${t('emptyNote')}</p></div><span class="empty-marker">01 — 02 — 03</span></div>`;return;}
  state.clips.forEach((clip,i)=>{const card=document.createElement('article');card.className='clip-card';const num=document.createElement('span');num.className='clip-number';num.textContent=String(i+1).padStart(2,'0');card.append(num);
    const thumb=document.createElement(state.thumbnail&&!clip.remote?'img':'div');thumb.className='clip-thumb';if(thumb.tagName==='IMG'){thumb.src=state.thumbnail;thumb.alt='';}else{thumb.innerHTML=icon('film');thumb.style.display='grid';thumb.style.placeItems='center';}card.append(thumb);
    const info=document.createElement('div');info.className='clip-card-info';const title=document.createElement('input');title.className='clip-card-title';title.value=clip.title;title.maxLength=100;title.setAttribute('aria-label',t('clipTitle'));title.addEventListener('change',()=>{clip.title=title.value.trim()||`${t('untitled')} ${i+1}`;title.value=clip.title;});info.append(title);
    const meta=document.createElement('div');meta.className='clip-meta';const time=document.createElement('time');time.dir='ltr';time.textContent=`${formatTime(clip.start)} — ${formatTime(clip.end)}`;const aspect=document.createElement('span');aspect.textContent=`· ${clip.ratio==='original'?t('original'):clip.ratio}${clip.ai?' · '+t('aiClip'):''}`;meta.append(time,aspect);info.append(meta);card.append(info);
    const actions=document.createElement('div');actions.className='clip-actions';const make=(label,name,fn,primary=false)=>{const b=document.createElement('button');b.className=primary?'primary':`icon-button ${name==='delete'?'danger':''}`;b.setAttribute('aria-label',t(label));b.title=t(label);b.innerHTML=icon(name)+(primary?`<span>${t(label)}</span>`:'');b.addEventListener('click',()=>Promise.resolve().then(fn).catch(fail));return b;};
    actions.append(make('preview','play',()=>previewClip(clip)));if(!clip.remote)actions.append(make('edit','edit',()=>{Object.assign(state,{start:clip.start,end:clip.end,ratio:clip.ratio,editingId:clip.id});$('#clip-title').value=clip.title;updateRange();$('#clip-title').scrollIntoView({behavior:'smooth',block:'center'});$('#clip-title').focus();}));actions.append(make('delete','delete',()=>{state.clips=state.clips.filter(c=>c.id!==clip.id);if(state.editingId===clip.id){state.editingId=null;$('#clip-title').value='';updateRange();}renderClips();toast(t('clipDeleted'));document.dispatchEvent(new CustomEvent('studio-clips'));}));actions.append(make('download','download',()=>clip.remote?downloadRemote(clip):exportClip(clip),true));card.append(actions);list.append(card);
  });
}
export function saveProject(){if(!state.file)throw new Error('restoreRemote');const plan={app:'autoclip-studio',version:1,created:new Date().toISOString(),source:{name:state.file.name,size:state.file.size,duration:state.duration},clips:state.clips.filter(c=>!c.remote).map(({title,start,end,ratio})=>({title,start,end,ratio}))};downloadBlob(new Blob([JSON.stringify(plan,null,2)],{type:'application/json'}),`${safeName(state.file.name.replace(/\.[^.]+$/,''))}.autoclip.json`);toast(t('projectSaved'));}
function restoreClips(plan){state.clips=plan.clips.map(c=>({...c,id:newId()}));state.editingId=null;renderClips();document.dispatchEvent(new CustomEvent('studio-clips'));}

export async function exportClip(clip){
 if(state.exporting)return;if(!state.file)throw new Error('needVideo');if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream||!(window.AudioContext||window.webkitAudioContext))throw new Error('unsupportedExport');if(clip.end-clip.start>180)throw new Error('longExport');
 const mime=['video/mp4;codecs=avc1.424028,mp4a.40.2','video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/mp4','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime)throw new Error('unsupportedExport');
 state.exporting=true;video.pause();state.previewEnd=null;const source=document.createElement('video');source.src=state.url;source.playsInline=true;source.preload='auto';source.style.cssText='position:fixed;bottom:0;left:0;width:1px;height:1px;opacity:.01;pointer-events:none;';document.body.append(source);const Audio=window.AudioContext||window.webkitAudioContext;const ctx=new Audio();const resume=ctx.resume();let stream,recorder,raf,timeout,wake,reason=null,finished=false;
 const cancel=key=>{reason=key||'exportCancelled';if(recorder?.state==='recording')recorder.stop();};state.cancelExport=cancel;
 const hidden=()=>{if(document.hidden)cancel('exportHidden');};document.addEventListener('visibilitychange',hidden);
 openDialog('export-dialog');$('#export-progress').value=0;$('#export-status').textContent='0%';
 try{
   if(navigator.wakeLock)try{wake=await navigator.wakeLock.request('screen');}catch{}
   await resume;const ready=waitMedia(source,'loadedmetadata');source.load();await ready;if(reason)throw new Error(reason);
   if(clip.start>0){const seek=waitMedia(source,'seeked');source.currentTime=clip.start;await seek;}
   const canvas=document.createElement('canvas');const size=exportDimensions(source.videoWidth,source.videoHeight,clip.ratio);Object.assign(canvas,size);const draw=canvas.getContext('2d',{alpha:false});const rect=cropRect(source.videoWidth,source.videoHeight,canvas.width,canvas.height);
   const audioSource=ctx.createMediaElementSource(source);const audioOut=ctx.createMediaStreamDestination();audioSource.connect(audioOut);stream=canvas.captureStream(30);for(const track of audioOut.stream.getAudioTracks())stream.addTrack(track);
   const chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:4_000_000,audioBitsPerSecond:128_000});const stopped=new Promise((resolve,reject)=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onerror=()=>reject(new Error('exportFailed'));recorder.onstop=()=>resolve();});
   function frame(){if(finished)return;draw.fillStyle='#000';draw.fillRect(0,0,canvas.width,canvas.height);draw.drawImage(source,rect.x,rect.y,rect.w,rect.h,0,0,canvas.width,canvas.height);document.dispatchEvent(new CustomEvent('studio-export-frame',{detail:{ctx:draw,canvas,time:source.currentTime}}));const progress=Math.max(0,Math.min(100,(source.currentTime-clip.start)/(clip.end-clip.start)*100));$('#export-progress').value=progress;$('#export-status').textContent=`${Math.floor(progress)}%`;if(source.currentTime>=clip.end-.015||source.ended){if(recorder.state==='recording')recorder.stop();return;}raf=requestAnimationFrame(frame);}
   recorder.start(500);await source.play();frame();timeout=setTimeout(()=>cancel('exportFailed'),((clip.end-clip.start)*1.8+30)*1000);await stopped;finished=true;
   if(reason)throw new Error(reason);source.pause();let blob=new Blob(chunks,{type:recorder.mimeType});if(blob.size<1000)throw new Error('exportFailed');if(mime.includes('webm'))blob=await fixWebmDuration(blob,(clip.end-clip.start)*1000,{logger:false});if(reason)throw new Error(reason);downloadBlob(blob,`${safeName(clip.title)}.${mime.includes('mp4')?'mp4':'webm'}`);toast(t('exportDone'));
 }catch(e){if(recorder?.state==='recording')recorder.stop();toast(t(['exportCancelled','exportHidden','unsupportedExport'].includes(e.message)?e.message:'exportFailed'),true);
 }finally{finished=true;cancelAnimationFrame(raf);clearTimeout(timeout);source.pause();source.removeAttribute('src');source.load();source.remove();stream?.getTracks().forEach(track=>track.stop());await ctx.close().catch(()=>{});if(wake)await wake.release().catch(()=>{});document.removeEventListener('visibilitychange',hidden);$('#export-dialog').close();state.exporting=false;state.cancelExport=null;}
}

async function api(path,options={},timeout=20000){if(!state.engine)throw new Error('needEngine');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeout);const external=options.signal;const abort=()=>controller.abort();external?.addEventListener('abort',abort,{once:true});if(external?.aborted)controller.abort();try{const headers=new Headers(options.headers);if(state.token)headers.set('Authorization','Bearer '+state.token);const r=await fetch(state.engine+path,{...options,headers,signal:controller.signal,credentials:'omit',redirect:'error',referrerPolicy:'no-referrer'});if(!r.ok)throw new Error('serverError');return r;}finally{clearTimeout(timer);external?.removeEventListener('abort',abort);}}
async function testConnection(e){e?.preventDefault();const result=$('#connection-result'),button=$('#test-connection');result.textContent=t('checking');result.classList.remove('error');button.disabled=true;const old={engine:state.engine,token:state.token};try{state.engine=normalizeServer($('#engine-url').value);state.token=$('#engine-token').value.trim();const r=await api('/api/v1/health/');const body=await r.json();if(!['healthy','ok'].includes(body.status)&&body.ok!==true)throw new Error('connectionFailed');state.connected=true;try{localStorage.setItem('autoclip-engine-url',state.engine);}catch{}result.textContent=t('connected');updateConnectionLabel();}catch(e){Object.assign(state,old);result.textContent=t(e.message==='invalidServer'?'invalidServer':'connectionFailed');result.classList.add('error');}finally{button.disabled=false;}}
function requireEngine(){if(state.connected)return true;toast(t('needEngine'));openDialog('connection-dialog');return false;}
const delay=(ms,signal)=>new Promise((resolve,reject)=>{if(signal?.aborted)return reject(new Error('analysisStopped'));const cancel=()=>{clearTimeout(timer);reject(new Error('analysisStopped'));};const timer=setTimeout(()=>{signal?.removeEventListener('abort',cancel);resolve();},ms);signal?.addEventListener('abort',cancel,{once:true});});
async function monitorProject(projectId,signal){const started=Date.now();while(Date.now()-started<45*60*1000){if(signal.aborted)throw new Error('analysisStopped');const project=await (await api(`/api/v1/projects/${encodeURIComponent(projectId)}?include_clips=true`,{signal})).json();if(project.status==='failed')throw new Error('analysisFailed');if(project.status==='completed'){const result=await(await api(`/api/v1/clips/?project_id=${encodeURIComponent(projectId)}&size=100`,{signal})).json();const clips=result.items||project.clips||[];const valid=clips.filter(c=>Number.isFinite(c.start_time)&&Number.isFinite(c.end_time)&&c.end_time>c.start_time);if(!valid.length)throw new Error('noHighlights');const local=Boolean(state.file);const remaining=100-state.clips.length;state.clips.push(...valid.slice(0,remaining).map(c=>({id:newId(),title:String(c.title||t('untitled')).slice(0,100),start:c.start_time,end:local?Math.min(c.end_time,state.duration):c.end_time,ratio:'original',ai:true,...(local?{}:{remote:{projectId,clipId:String(c.id),engine:state.engine}})})).filter(c=>c.end>c.start));renderClips();document.dispatchEvent(new CustomEvent('studio-clips'));return;}$('#analysis-status').textContent=t('processing');await delay(4000,signal);}throw new Error('analysisTimeout');}
async function analyze(){if(!state.file){toast(t('needVideo'),true);return;}if(!requireEngine())return;const controller=new AbortController();state.analysisAbort=controller;openDialog('analysis-dialog');$('#analysis-progress').removeAttribute('value');$('#analysis-status').textContent=t('uploading');$('#analyze').disabled=true;try{let id=state.projectId;if(!id){const form=new FormData();form.append('video_file',state.file);form.append('project_name',state.file.name.slice(0,190));form.append('video_category','default');const project=await(await api('/api/v1/projects/upload',{method:'POST',body:form,signal:controller.signal},10*60*1000)).json();id=project.id;if(!id)throw new Error('analysisFailed');state.projectId=id;}await api(`/api/v1/projects/${encodeURIComponent(id)}/process`,{method:'POST',signal:controller.signal},60000);$('#analysis-status').textContent=t('processing');await monitorProject(id,controller.signal);toast(t('analysisDone'));}catch(e){toast(t(controller.signal.aborted?'analysisStopped':e.message==='analysisTimeout'?'analysisTimeout':e.message==='noHighlights'?'noHighlights':'analysisFailed'),true);}finally{$('#analysis-dialog').close();state.analysisAbort=null;$('#analyze').disabled=false;}}
async function importLink(){let platform;try{platform=videoPlatform($('#video-url').value);}catch{toast(t('invalidLink'),true);return;}if(!requireEngine())return;if(state.clips.length||state.file){requestReplacement(()=>startLinkImport(platform));}else await startLinkImport(platform);}
async function startLinkImport(platform){const controller=new AbortController();state.analysisAbort=controller;openDialog('analysis-dialog');$('#analysis-progress').removeAttribute('value');$('#analysis-status').textContent=t('importing');$('#import-link').disabled=true;try{const task=await(await api(`/api/v1/${platform}/download`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:$('#video-url').value.trim(),project_name:t('importTitle'),video_category:'default'}),signal:controller.signal},120000)).json();const taskId=task.task_id||task.id;if(!taskId)throw new Error('analysisFailed');let projectId=task.project_id;let ready=false;const started=Date.now();while(Date.now()-started<30*60*1000){const status=await(await api(`/api/v1/${platform}/tasks/${encodeURIComponent(taskId)}`,{signal:controller.signal})).json();if(status.status==='failed')throw new Error('analysisFailed');if(status.status==='completed'){projectId=status.project_id||projectId;ready=true;break;}if(Number.isFinite(status.progress))$('#analysis-progress').value=Math.min(100,Math.max(0,status.progress));await delay(4000,controller.signal);}if(!ready||!projectId)throw new Error('analysisTimeout');video.pause();state.file=null;state.clips=[];state.projectId=projectId;state.duration=0;if(state.url)URL.revokeObjectURL(state.url);state.url=null;$('#player-area').hidden=true;$('#import-area').hidden=false;for(const id of ['start-time','end-time','start-range','end-range','add-cut','preview-cut'])$('#'+id).disabled=true;renderClips();await api(`/api/v1/projects/${encodeURIComponent(projectId)}/process`,{method:'POST',signal:controller.signal},60000);$('#analysis-progress').removeAttribute('value');await monitorProject(projectId,controller.signal);toast(t('analysisDone'));}catch(e){toast(t(controller.signal.aborted?'analysisStopped':e.message==='analysisTimeout'?'analysisTimeout':'analysisFailed'),true);}finally{$('#analysis-dialog').close();state.analysisAbort=null;$('#import-link').disabled=false;}}
async function remoteBlob(clip){if(!state.connected||clip.remote.engine!==state.engine)throw new Error('needEngine');return(await api(`/api/v1/projects/${encodeURIComponent(clip.remote.projectId)}/download?clip_id=${encodeURIComponent(clip.remote.clipId)}`,{},120000)).blob();}
async function downloadRemote(clip){toast(t('exporting'));const blob=await remoteBlob(clip);downloadBlob(blob,`${safeName(clip.title)}.mp4`);toast(t('exportDone'));}
async function previewRemote(clip){const blob=await remoteBlob(clip);const url=URL.createObjectURL(blob);let modal=$('#remote-preview');if(!modal){modal=document.createElement('dialog');modal.id='remote-preview';modal.innerHTML=`<button class="icon-button" aria-label="${t('close')}">${icon('x')}</button><video controls playsinline style="width:100%;max-height:65vh"></video>`;document.body.append(modal);modal.querySelector('button').onclick=()=>modal.close();}const player=modal.querySelector('video');player.src=url;modal.addEventListener('close',()=>{player.pause();player.removeAttribute('src');URL.revokeObjectURL(url);},{once:true});modal.showModal();await player.play();}

hydrateIcons();
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.lang)));
document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$('#'+b.dataset.close).close()));
for(const id of ['connection-nav','connection-chip'])$('#'+id).onclick=()=>openDialog('connection-dialog');
for(const id of ['help-nav','mobile-help'])$('#'+id).onclick=()=>openDialog('help-dialog');
for(const id of ['choose-video','replace-video','new-project'])$('#'+id).onclick=()=>requestReplacement(inputFile);
$('#confirm-replace').onclick=()=>{$('#confirm-dialog').close();const action=pendingAction;pendingAction=null;action?.();};
$('#file-input').onchange=e=>loadVideo(e.target.files[0]).catch(fail);
for(const ev of ['dragenter','dragover'])$('#dropzone').addEventListener(ev,e=>{e.preventDefault();$('#dropzone').classList.add('dragging');});
for(const ev of ['dragleave','drop'])$('#dropzone').addEventListener(ev,e=>{e.preventDefault();$('#dropzone').classList.remove('dragging');});
$('#dropzone').addEventListener('drop',e=>{const f=e.dataTransfer.files[0];requestReplacement(()=>loadVideo(f).catch(fail));});
function selectSource(which){for(const name of ['upload','link']){const active=name===which;$('#'+name+'-tab').classList.toggle('selected',active);$('#'+name+'-tab').setAttribute('aria-selected',String(active));$('#'+name+'-tab').tabIndex=active?0:-1;$('#'+name+'-pane').hidden=!active;}}
for(const name of ['upload','link']){$('#'+name+'-tab').onclick=()=>selectSource(name);$('#'+name+'-tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const dest=e.key==='Home'?'upload':e.key==='End'?'link':name==='upload'?'link':'upload';selectSource(dest);$('#'+dest+'-tab').focus();}};}
$('#start-range').oninput=e=>{state.start=Math.min(Number(e.target.value),Math.max(0,state.end-.1));updateRange();};$('#end-range').oninput=e=>{state.end=Math.max(Number(e.target.value),state.start+.1);updateRange();};
for(const id of ['start-time','end-time'])$('#'+id).onchange=()=>{try{readRange();}catch(e){fail(e);updateRange();}};
document.querySelectorAll('[data-ratio]').forEach(b=>b.onclick=()=>{state.ratio=b.dataset.ratio;updateRange();});
$('#add-cut').onclick=()=>{try{addClip();}catch(e){fail(e);}};$('#preview-cut').onclick=()=>{try{readRange();previewClip({start:state.start,end:state.end}).catch(fail);}catch(e){fail(e);}};
video.addEventListener('timeupdate',()=>{$('#playhead').style.left=`${state.duration?video.currentTime/state.duration*100:0}%`;if(state.previewEnd!==null&&video.currentTime>=state.previewEnd){video.pause();state.previewEnd=null;}});
$('#save-project').onclick=()=>{try{saveProject();}catch(e){fail(e);}};
$('#restore-project').onclick=()=>{$('#project-input').value='';$('#project-input').click();};
$('#project-input').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2_000_000)throw new Error('invalidProject');const plan=parseProject(JSON.parse(await f.text()));const run=()=>{if(state.file?.name===plan.source.name&&state.file?.size===plan.source.size&&Math.abs(state.duration-plan.source.duration)<.2){restoreClips(plan);toast(t('projectRestored'));}else{state.pendingProject=plan;toast(t('chooseOriginal')+plan.source.name);inputFile();}};requestReplacement(run);}catch{toast(t('invalidProject'),true);}};
$('#cancel-export').onclick=()=>state.cancelExport?.();$('#export-dialog').addEventListener('cancel',e=>{e.preventDefault();state.cancelExport?.();});
$('#connection-form').onsubmit=testConnection;$('#disconnect').onclick=()=>{state.connected=false;state.engine='';state.token='';state.projectId=null;$('#engine-url').value='';$('#engine-token').value='';$('#connection-result').textContent=t('disconnected');try{localStorage.removeItem('autoclip-engine-url');}catch{}updateConnectionLabel();};
try{$('#engine-url').value=localStorage.getItem('autoclip-engine-url')||'';}catch{}
$('#analyze').onclick=analyze;$('#import-link').onclick=importLink;$('#stop-analysis').onclick=()=>{state.analysisAbort?.abort();$('#analysis-dialog').close();};$('#analysis-dialog').addEventListener('cancel',()=>state.analysisAbort?.abort());
window.addEventListener('beforeunload',e=>{if(state.exporting||state.clips.length){e.preventDefault();e.returnValue='';}});
setLanguage(state.lang);
if(document.modelContext?.registerTool){const ctl=new AbortController();window.addEventListener('pagehide',()=>ctl.abort(),{once:true});const register=tool=>Promise.resolve(document.modelContext.registerTool(tool,{signal:ctl.signal})).catch(()=>{});register({name:'read_clip_workspace',description:'Read the current video, selected time range and staged clips without changing them.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({video:state.file?.name||null,duration:state.duration,selection:{start:state.start,end:state.end,ratio:state.ratio},clips:state.clips.map(({id,title,start,end,ratio})=>({id,title,start,end,ratio}))})});register({name:'stage_video_selection',description:'Set a start/end range for the loaded local video; this does not export or upload anything.',inputSchema:{type:'object',properties:{start:{type:'number',minimum:0},end:{type:'number',minimum:0},ratio:{enum:['original','9:16','16:9']}},required:['start','end'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>setSelection(input.start,input.end,input.ratio||'original')});register({name:'add_selection_to_clips',description:'Add the selected time range to the visible clip list; no export or publication occurs.',inputSchema:{type:'object',properties:{title:{type:'string',maxLength:100}},required:['title'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input.title!=='string'||input.title.length>100)throw new Error('Invalid title');return addClip(input.title);}});}
